  display: flex;
  justify-content: space-between;
  margin-top: 9px;
  color: var(--dim-2);
  font-size: 6px;
  font-weight: 600;
  letter-spacing: 0.16em;
}

/* Animations */
@keyframes breathe {
  0%, 100% { opacity: 0.55; transform: scale(0.88); }
  50% { opacity: 1; transform: scale(1.08); }
}

@keyframes feed-in {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes toast-out {
  from { opacity: 1; transform: translateY(0); }
  to { opacity: 0; transform: translateY(-4px); }
}

@keyframes dialog-in {
  from { opacity: 0; transform: translateY(9px) scale(0.99); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}

@keyframes boot-float {
  0%, 100% { transform: translateY(0); opacity: 0.8; }
  50% { transform: translateY(-5px); opacity: 1; }
}

@media (max-width: 1180px) {

.toast.is-leaving {
  animation: toast-out 240ms ease both;
}

/* Help dialog */
.help-dialog {
  width: min(690px, calc(100vw - 32px));
  max-height: calc(100dvh - 40px);
  overflow: auto;
  padding: 27px 28px 20px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    linear-gradient(150deg, rgba(25, 26, 27, 0.96), rgba(7, 8, 9, 0.98));
  color: var(--text);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.65), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.help-dialog::backdrop {
  background: rgba(3, 4, 5, 0.66);
  backdrop-filter: blur(8px);
}

.help-dialog[open] {
  animation: dialog-in 260ms cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

.dialog-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.help-dialog h2 {
  margin: 20px 0 10px;
  font-family: var(--serif);
  font-size: clamp(34px, 5vw, 49px);
  line-height: 1;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.help-dialog h2 em {
  color: var(--gold-bright);
  font-style: normal;
}

.dialog-lede {
  max-width: 510px;
  margin: 0;
  color: #a8a297;
  font-size: 12px;
  line-height: 1.7;
  letter-spacing: 0.01em;
}

.dialog-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  margin-top: 25px;
  padding-top: 20px;
  border-top: 1px solid var(--line-soft);
}

.shortcut-list {
  margin: 10px 0 0;
}

.shortcut-list div {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 5px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.035);
}

.shortcut-list dt {
  color: #d2cbbf;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.shortcut-list dd {
  margin: 0;
  color: var(--dim-2);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-align: right;
}

kbd {
  display: inline-block;
  min-width: 16px;
  padding: 2px 4px;
  border: 1px solid var(--line);
  border-radius: 3px;
  color: #b8b2a6;
  font-family: var(--sans);
  font-size: 7px;
  line-height: 1;
  text-align: center;
}

.dialog-note {
  display: flex;
