    rosterVisible: document.querySelector('.right-rail').getBoundingClientRect().height > 0,
    operationsVisible: document.querySelector('.operations-bar').getBoundingClientRect().height > 0,
  }))

  await page.locator('[data-agent-id="iris"]').click()
  await page.waitForTimeout(1200)
