      name: document.querySelector('.agent-name')?.textContent,
      panelBottom: Math.round(panel.bottom),
      rosterTop: Math.round(roster.top),
      gap: Math.round(roster.top - panel.bottom),
      cameraMode: document.querySelector('#camera-mode')?.textContent,
    }
  })

  await page.locator('#agent-panel [data-action="clear"]').click()
  await page.waitForTimeout(1400)
